const KEY='offmarket-workspace-v1',empty={leads:[],buyers:[]};let data;try{data={...empty,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{data={...empty}}let selected=null;const $=s=>document.querySelector(s),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const save=()=>localStorage.setItem(KEY,JSON.stringify(data));function tab(name){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===name));document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('#crumb').textContent=document.querySelector(`[data-page="${name}"]`)?.textContent.trim()||name;render()}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>tab(b.dataset.page));function card(l){return `<article class="card lead-card${selected===l.id?' selected':''}" data-id="${l.id}"><b>${esc(l.address)}</b><p>${esc([l.city,l.county,l.state,l.zip].filter(Boolean).join(' · '))}</p><span>${esc(l.status||'Needs review')} · checked ${esc(l.checked||'not yet')}</span><p>${esc(l.sourceNotes||'No source notes yet.')}</p></article>`}function render(){const q=($('#search')?.value||'').toLowerCase(),status=$('#filterStatus')?.value||'',leads=data.leads.filter(l=>(!q||JSON.stringify(l).toLowerCase().includes(q))&&(!status||l.status===status));$('#leadCards').innerHTML=leads.length?leads.map(card).join(''):'<div class="card">No matching leads. Add one to start a research file.</div>';$('#leadTable').innerHTML=data.leads.length?data.leads.map(card).join(''):'No property leads yet.';document.querySelectorAll('.lead-card').forEach(c=>c.onclick=()=>{selected=c.dataset.id;renderDetail();document.querySelectorAll('.lead-card').forEach(x=>x.classList.toggle('selected',x.dataset.id===selected))});$('#metrics').innerHTML=[['Property leads',data.leads.length],['Needs review',data.leads.filter(l=>(l.status||'Needs review')==='Needs review').length],['Investor contacts',data.buyers.length],['Verified records',data.leads.filter(l=>l.status==='Verified').length]].map(([k,v])=>`<div class="metric"><b>${v}</b><span>${k}</span></div>`).join('');$('#buyerList').innerHTML=data.buyers.length?data.buyers.map((b,i)=>`<article class="card"><b>${esc(b.name)}</b><p>${esc(b.market)} · ${esc(b.types)}</p><p>${esc(b.budget)} ${esc(b.contact)}</p><p>${esc(b.notes)}</p><button data-delbuyer="${i}">Remove</button></article>`).join(''):'<div class="card">No buyers saved.</div>';document.querySelectorAll('[data-delbuyer]').forEach(b=>b.onclick=()=>{data.buyers.splice(+b.dataset.delbuyer,1);save();render()});renderDetail()}function renderDetail(){const l=data.leads.find(x=>x.id===selected);const target=$('#detail');if(!l){target.innerHTML='<p>Select a lead to inspect its research notes. Add source links and verify facts with public records.</p>';return}target.innerHTML=`<span class="eyebrow">${esc(l.status||'Needs review')}</span><h2>${esc(l.address)}</h2><p>${esc([l.city,l.county,l.state,l.zip].filter(Boolean).join(' · '))}</p><div class="facts"><label>Property type<select data-field="type"><option>Unconfirmed</option><option>Residential</option><option>Multifamily</option><option>Land</option><option>Commercial</option></select></label><label>Status<select data-field="status"><option>Needs review</option><option>Verified</option><option>Contacted</option><option>Closed / archive</option></select></label><label>Bedrooms<input data-field="beds" type="number" min="0" value="${esc(l.beds)}"></label><label>Bathrooms<input data-field="baths" type="number" min="0" step="0.5" value="${esc(l.baths)}"></label><label>Square feet<input data-field="sqft" type="number" min="0" value="${esc(l.sqft)}"></label><label>Parcel / GIS<input data-field="parcel" value="${esc(l.parcel)}"></label><label>Last recorded sale price<input data-field="sale" type="number" min="0" value="${esc(l.sale)}"></label><label>Last sale date<input data-field="saleDate" type="date" value="${esc(l.saleDate)}"></label><label>Source / ownership evidence URL<input data-field="evidence" type="url" value="${esc(l.evidence||l.source)}"></label><label>Date checked<input data-field="checked" type="date" value="${esc(l.checked)}"></label></div><label>Condition notes<textarea data-field="condition">${esc(l.condition)}</textarea></label><label>Private research notes<textarea data-field="notes">${esc(l.notes)}</textarea></label><h3>Optional estimate worksheet</h3><p>Enter figures you independently support. This is arithmetic only, not a valuation or offer recommendation.</p><div class="facts"><label>Estimated after-repair value<input data-field="arv" type="number" min="0" value="${esc(l.arv)}"></label><label>Estimated repairs<input data-field="repairs" type="number" min="0" value="${esc(l.repairs)}"></label><label>Other costs<input data-field="costs" type="number" min="0" value="${esc(l.costs)}"></label><label>Target margin %<input data-field="margin" type="number" min="0" max="100" value="${esc(l.margin||20)}"></label></div><button id="calc">Calculate user-entered scenario</button><p id="calcResult">${scenario(l)}</p><div class="actions"><a href="${esc(l.source||'#')}" target="_blank" rel="noopener">Open source ↗</a> <button id="print">Print buyer deal sheet</button> <button id="delete" class="danger">Delete lead</button></div>`;for(const el of target.querySelectorAll('[data-field]')){el.value=l[el.dataset.field]??el.value;el.onchange=()=>{l[el.dataset.field]=el.value;save();render()}}$('#calc').onclick=()=>{$('#calcResult').textContent=scenario(l)};$('#delete').onclick=()=>{data.leads=data.leads.filter(x=>x.id!==l.id);selected=null;save();render()};$('#print').onclick=()=>window.print();}function scenario(l){const a=+l.arv||0,r=+l.repairs||0,c=+l.costs||0,m=(+l.margin||0)/100;if(!a)return'Enter your independently researched figures to see a simple scenario.';return`Entered values: ARV $${a.toLocaleString()} − repairs $${r.toLocaleString()} − other costs $${c.toLocaleString()} − ${Math.round(m*100)}% target margin ($${Math.round(a*m).toLocaleString()}) = $${Math.max(0,Math.round(a-r-c-a*m)).toLocaleString()} remaining before financing, taxes, closing costs, title issues, or other expenses.`}function addLead(){ $('#leadDialog').showModal()}$('#addLead').onclick=addLead;$('#addLead2').onclick=addLead;$('#leadForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(e.submitter?.value==='cancel'){$('#leadDialog').close();return}const l=Object.fromEntries(f.entries());Object.assign(l,{id:crypto.randomUUID(),created:new Date().toISOString(),status:'Needs review'});data.leads.unshift(l);selected=l.id;save();e.target.reset();$('#leadDialog').close();render()};$('#search').oninput=render;$('#filterStatus').onchange=render;$('#buyerForm').onsubmit=e=>{e.preventDefault();data.buyers.push(Object.fromEntries(new FormData(e.target).entries()));save();e.target.reset();render()};$('#export').onclick=()=>{const b=new Blob([JSON.stringify({version:1,exported:new Date().toISOString(),...data},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='off-market-deal-finder-backup.json';a.click();URL.revokeObjectURL(a.href)};$('#import').onchange=async e=>{try{const j=JSON.parse(await e.target.files[0].text());if(!Array.isArray(j.leads)||!Array.isArray(j.buyers))throw 0;data={leads:j.leads,buyers:j.buyers};save();render();alert('Backup imported.')}catch{alert('That backup file could not be read.')}e.target.value=''};$('#buildScript').onclick=()=>{$('#script').textContent=`Hello, my name is ____. I’m calling about the public notice for ${$('#contactAddress').value||'[property address]'}. I’m trying to verify the public status, not ask for private borrower information.\n\nQuestions:\n${$('#questions').value}\n\nI’ll check the original notice and county records and follow up only through your published business channel.`};$('#buyerScript').onclick=()=>{$('#buyerScriptOut').textContent=`Hello, I’m reviewing a property lead in [market]. I have not verified availability, ownership, condition, title, value, or sale status. If you are interested, I can share the public source and evidence I have gathered for your own review.`};tab('desk');
